import subprocess, random, string
def rand(s):
    pat="TEST-(.*)"
    content="TEST-"+s
    open("t.txt","w").write(content)
    p=subprocess.run(["/workspace/executable","--additional-pattern",pat,"t.txt"], capture_output=True, text=True)
    return p.returncode!=0

def gen_with_unique(charset, length, uniq, seed):
    random.seed(seed)
    uniq_chars=random.sample(charset, uniq)
    s=''.join(random.choice(uniq_chars) for _ in range(length))
    lst=list(s)
    for i,ch in enumerate(uniq_chars):
        lst[i]=ch
    random.shuffle(lst)
    return ''.join(lst)

for length in [12,15,16,20,30]:
    print(f"=== upper len{length} uniq threshold ===")
    for uniq in [6,8,10,12,14,16,18,20]:
        if uniq>length:
            continue
        passes=0
        for seed in range(10):
            s=gen_with_unique(string.ascii_uppercase, length, uniq, seed)
            if rand(s):
                passes+=1
        print(f"uniq{uniq}: {passes}/10")
