def shannon_entropy(s):
    if isinstance(s, bytes):
        n = len(s)
        if n == 0:
            return 0.0
        c = Counter(s)
        ent = 0.0
        for v in c.values():
            p = v / n
            ent -= p * math.log2(p)
        return ent
    else:
        n = len(s)
        if n == 0:
            return 0.0
        c = Counter(s)
        ent = 0.0
        for v in c.values():
            p = v / n
            ent -= p * math.log2(p)
        return ent

def is_random(s):
    if s is None:
        return False
    if isinstance(s, str):
        try:
            b = s.encode('latin1')
        except Exception:
            b = s.encode('utf-8', errors='ignore')
        return is_random(b)
    n = len(s)
    if n == 0:
        return False
    if n == 1:
        return True
    is_pure_lower = True
    for bv in s:
        if not (97 <= bv <= 122):
            is_pure_lower = False
            break
    if is_pure_lower and n >= 10:
        return False
    is_all_digits = True
    for bv in s:
        if not (48 <= bv <= 57):
            is_all_digits = False
            break
    if is_all_digits and n >= 8:
        lst = list(s)
        if sorted(lst) == lst or sorted(lst, reverse=True) == lst:
            return False
    ent = shannon_entropy(s)
    thresh = min(2.8, math.log2(n)) if n > 1 else 0.0
    if ent + 1e-9 < thresh:
        return False
    return True

