def translate_pattern(pat):
    i = 0
    n = len(pat)
    res = ""
    while i < n:
        c = pat[i]
        if c == '*':
            if i + 1 < n and pat[i+1] == '*':
                if i == 0 and i + 2 < n and pat[i+2] == '/':
                    res += "(.*/)?"
                    i += 3
                    continue
                else:
                    res += ".*"
                    i += 2
                    continue
            else:
                res += "[^/]*"
                i += 1
                continue
        elif c == '?':
            res += "[^/]"
            i += 1
            continue
        elif c == '[':
            k = pat.find(']', i+1)
            if k == -1:
                res += "\\["
                i += 1
                continue
            else:
                content = pat[i+1:k]
                if content.startswith('!'):
                    content = '^' + content[1:]
                res += "[" + content + "]"
                i = k + 1
                continue
        else:
            if c in ".^$+{}()|\\":
                res += "\\" + c
            else:
                res += c
            i += 1
            continue
    return res

